import{_ as n,a0 as p,w as i,s as l,ao as d,I as s,x as a,a1 as r,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"“安全”這個熱詞：應避免使用還是該更直接了當？ | LCTT x X-CMD","titleTemplate":false,"description":"“安全”這個熱詞：應避免使用還是該更直接了當？ | LCTT (202310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"“安全”這個熱詞：應避免使用還是該更直接了當？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"“安全”這個熱詞：應避免使用還是該更直接了當？ | LCTT (202310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202310/20220920 Security buzzwords to avoid and what to say instead","title":"“安全”這個熱詞：應避免使用還是該更直接了當？","tag":"202310","desc":""},"relativePath":"202310/20220920 Security buzzwords to avoid and what to say instead.md","filePath":"[post].md"}'),u={name:"202310/20220920 Security buzzwords to avoid and what to say instead.md"};function m(h,t,g,f,b,T){const e=p("Link");return i(),l("div",null,[t[15]||(t[15]=d('<h1 id="安全-這個熱詞-應避免使用還是該更直接了當" tabindex="-1">“安全”這個熱詞：應避免使用還是該更直接了當？ <a class="header-anchor" href="#安全-這個熱詞-應避免使用還是該更直接了當" aria-label="Permalink to ““安全”這個熱詞：應避免使用還是該更直接了當？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202310/28/095718zso6aaitoyyv4ain.jpg" alt=""></p><blockquote><p>思考一下，如何在你的開源項目中真正定義安全性吧。</p></blockquote><p>科技行業以創造“熱詞”而小有名氣，當然，其他行業也是如此。譬如，“故事驅動”和“輕規則”是當下流行的桌遊概念，“解構”的漢堡和墨西哥捲餅在高級餐廳頗受歡迎。然而，技術熱詞的問題在於，它們可能直接影響你的生活。當某人標榜應用程序“安全”，以此來吸引你使用他們的產品，產品實際上是在暗示一種承諾：“安全”的含義就是它是安全的，它值得你的使用與信任。但問題是，“安全”這個詞可能指的是許多事情，技術行業常將它用作一個過於泛化的術語，以至於它逐漸失去了實際含義。</p><p>由於“安全”一詞可能含義豐富，也可能一無是處，使用它就需要慎之又慎。事實上，最好是儘量避免使用這個詞，取而代之的是，訴諸你真正要表達的東西。</p><h3 id="當-安全-意味着加密" tabindex="-1">當 “安全” 意味着加密 <a class="header-anchor" href="#當-安全-意味着加密" aria-label="Permalink to “當 “安全” 意味着加密”">​</a></h3><p>有時候，“安全” 會被作為 <em>加密</em> 的非常不明確的簡短表述。在這種情況下，“安全” 指的是，對於外部觀察者想要竊聽你的數據，要經過一定的困難。</p><p><strong>避免這樣表述：</strong>“本網站穩如磐石且安全無憂。”</p><p>聽起來很棒？你可能會想像一個擁有多重二次驗證、零知識證明數據存儲以及堅決的匿名策略的網站。</p><p><strong>你可以這麼説：</strong>“本網站承諾有 99% 的在線時間，並且其流量都通過 SSL 進行加密和驗證。”</p><p>這樣一來，承諾的含義變得清晰了，同時也明確了實現 “安全” 的方法（即使用 SSL）以及 “安全“ 的作用範圍是什麼。</p><p>注意，這裏並未對隱私或匿名做出任何明確的承諾。</p><h3 id="當-安全-意味着訪問限制" tabindex="-1">當 “安全” 意味着訪問限制 <a class="header-anchor" href="#當-安全-意味着訪問限制" aria-label="Permalink to “當 “安全” 意味着訪問限制”">​</a></h3><p>有時，“安全” 這個詞是指應用程序或設備的訪問權限。如果沒有明確的解釋，“安全” 可能涵蓋從無效的“隱蔽即安全”模式，到簡單的 htaccess 密碼，直到生物識別掃描器等各種概念。</p><p><strong>避免這樣表述：</strong>“我們已經為你防護好了系統。”</p><p><strong>你可以這麼説：</strong>“我們的系統採用了二步驗證法。”</p><h3 id="當-安全-意味着數據存儲" tabindex="-1">當 “安全” 意味着數據存儲 <a class="header-anchor" href="#當-安全-意味着數據存儲" aria-label="Permalink to “當 “安全” 意味着數據存儲”">​</a></h3><p>“安全” 這個詞也可以指你的數據在服務器或設備上的儲存方法。</p><p><strong>避免這樣表述：</strong>“這個設備在數據存儲上考慮了安全因素。”</p><p><strong>你可以這麼説：</strong>“這個設備利用全盤加密技術來保護你的數據。”</p><p>當提到遠程存儲時，“安全” 可能更多指的是誰可以訪問存儲數據。</p><p><strong>避免這樣表述：</strong>“你的數據是安全的。”</p><p><strong>你可以這麼説：</strong>“你的數據經過 PGP 加密，僅你持有私鑰。”</p><h3 id="當-安全-意味着隱私" tabindex="-1">當 “安全” 意味着隱私 <a class="header-anchor" href="#當-安全-意味着隱私" aria-label="Permalink to “當 “安全” 意味着隱私”">​</a></h3><p>今天，“隱私” 一詞幾乎和 “安全” 一樣寬泛且模糊。一方面，“安全” 似乎必然就涉及 “隱私”，然而，這僅在 &#39;安全&#39; 有明確定義時才成立。是因為設有密碼阻止外人進入所以稱之為私有嗎？還是因為數據已加密且僅你擁有密鑰所以歸為私有？又或者，由於存儲你數據的廠商除了 IP 地址外對你一無所知，這才算是私有？光是口頭聲明 “隱私”，就像未經説明就聲明 “安全” 一樣，是不夠的。</p><p><strong>避免這樣表述：</strong>“你的數據在我們這裏是安全的。”</p><p><strong>你可以這麼説：</strong>“你的數據經 PGP 加密，且只有你擁有私鑰。我們不需要你的任何個人信息，唯一能識別你的只有你的 IP 地址。”</p><p>一些網站會聲明 IP 地址在日誌中保留期限，及非經法律授權絕不向執法部門交出用户數據等諸多承諾。雖然這些並不屬於技術 “安全” 的範疇，但它們全都涉及的是信任度，你不能將這些看作是技術規格。</p><h3 id="明確所説" tabindex="-1">明確所説 <a class="header-anchor" href="#明確所説" aria-label="Permalink to “明確所説”">​</a></h3><p>科技是個複雜的話題，極易引發混淆。溝通是至關重要的，雖然有時候簡拼和專有名詞在某些場合可能管用，但通常來説，講明白總是比較好的。當你對你的項目的 “安全” 感到自豪，不要只用模糊的詞語進行簡述。向其他人明確你具體做了什麼來保護你的用户，同時也要明確你認為哪些事物已超出你的考量範圍，並要經常進行這樣的溝通。“安全” 是個好特點，但它的涵蓋面過廣，所以請勿畏於誇讚自己在某個具體方向上的特別之處。</p><p><em>（題圖：MJ/b8cc54ee-5556-4106-b9fa-b08539452aa7）</em></p><hr>',32)),s("p",null,[t[1]||(t[1]=a("via: ",-1)),r(e,{href:"https://opensource.com/article/22/9/security-buzzword-alternatives"},{default:o(()=>[...t[0]||(t[0]=[a("https://opensource.com/article/22/9/security-buzzword-alternatives",-1)])]),_:1})]),s("p",null,[t[6]||(t[6]=a("作者：",-1)),r(e,{href:"https://opensource.com/users/seth"},{default:o(()=>[...t[2]||(t[2]=[a("Seth Kenlon",-1)])]),_:1}),t[7]||(t[7]=a(" 選題：",-1)),r(e,{href:"https://github.com/lkxed"},{default:o(()=>[...t[3]||(t[3]=[a("lkxed",-1)])]),_:1}),t[8]||(t[8]=a(" 譯者：",-1)),r(e,{href:"https://linux.cn/lctt/ChatGPT"},{default:o(()=>[...t[4]||(t[4]=[a("ChatGPT",-1)])]),_:1}),t[9]||(t[9]=a(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[5]||(t[5]=[a("wxy",-1)])]),_:1})]),s("p",null,[t[12]||(t[12]=a("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[10]||(t[10]=[a("LCTT",-1)])]),_:1}),t[13]||(t[13]=a(" 原創編譯，",-1)),r(e,{href:"https://linux.cn/"},{default:o(()=>[...t[11]||(t[11]=[a("Linux中國",-1)])]),_:1}),t[14]||(t[14]=a(" 榮譽推出",-1))])])}const k=n(u,[["render",m]]);export{C as __pageData,k as default};
